// Asumimos que msg.payload contiene el array de objetos de alarma
msg.payload = msg.payload.map(alarm => {
    let severity, icon;

    // Determinar la severidad y el icono basado en el texto de la Alerta
    if (alarm.Alerta.includes('Muy Alta') || alarm.Alerta.includes('Muy Baja')) {
        severity = 'high';
        icon = '⚠️';
    } else if (alarm.Alerta.includes('Alta') || alarm.Alerta.includes('Baja')) {
        severity = 'medium';
        icon = '⚠';
    } else {
        severity = 'low';
        icon = 'ℹ️';
    }

    // Determinar el color basado en AlarmColor
    let textColor;
    switch (alarm.AlarmColor) {
        case '#8E0000':
            textColor = '#ff6b6b'; // Rojo más brillante para tema oscuro
            break;
        case '#FFFF00':
            textColor = '#feca57'; // Amarillo más oscuro para mejor contraste
            break;
        default:
            textColor = '#48dbfb'; // Azul claro por defecto
    }

    // Retornar el objeto de alarma con las nuevas propiedades
    return {
        ...alarm,
        severity,
        icon,
        textColor
    };
});

return msg;

