func:
// Recuperación de variables globales

let dit = global.get("UIT_2001_DENSITY");
if (dit===null || dit.PV===null) {
    node.warn("No hay datos de densidad en global UIT_2001_DENSITY");
    return [null, null]; // No hay datos, no enviamos nada por ninguna salida
}

let currentDensity = parseFloat(dit.PV);
let producto = 3; // ID por defecto (GLP/Mezcla)
let inLineProduct = global.get("INLINE_PRODUCT") || "Mezcla";
let IsChangeProduct = false;

// Variables para los mensajes de salida
let msgUpdate = null;
let msgInsert = null;
let msgPause = null;

// --- Lógica de Detección de Producto ---

// BUTANO (Rango 557 - 585)
if (currentDensity >= 557 && currentDensity <= 585 && inLineProduct !== "Butano") {
    producto = 2;  // ID Butano
    inLineProduct = "Butano";
    global.set("INLINE_PRODUCT", inLineProduct);
    IsChangeProduct = true;
}
// PROPANO (Rango 480 - 500)
else if (currentDensity >= 480 && currentDensity <= 500 && inLineProduct !== "Propano") {
    producto = 1;  // ID Propano
    inLineProduct = "Propano";
    global.set("INLINE_PRODUCT", inLineProduct);
    IsChangeProduct = true;
}
// MEZCLA (Rango intermedio 500 - 557)
else if (currentDensity > 500 && currentDensity < 557 && inLineProduct !== "Mezcla") {
    producto = 3;  // ID Mezcla
    inLineProduct = "Mezcla";
    global.set("INLINE_PRODUCT", inLineProduct);
    IsChangeProduct = true;

    if (global.get("SEL_CISTERNA") === "CISTERNA1") {
        if (global.get("STATUS_CISTERNA1") === 2) {
            global.set("STATUS_CISTERNA1", 3);  //Pausar Bache
            global.set("SEND_STATUS_CISTERNA1", true);
            msgPause = {
                payload: "Pause",
            }
        }
    }
    else{
         if (global.get("STATUS_CISTERNA2") === 2) {
            global.set("STATUS_CISTERNA2", 3);  //Pausar Bache
            global.set("SEND_STATUS_CISTERNA1", true);
            msgPause = {
                payload: "Pause",
            }
        }

    }


}


// --- Generación de Mensajes de Salida ---

if (IsChangeProduct === true) {
    let now = new Date();
    // Formato de fecha ISO para SQL (YYYY-MM-DD HH:MM:SS)
    let sqlDate = now.toLocaleString().replaceAll('/', '-');
    sqlDate = sqlDate.replace(',', ' ');

    // 1. CREAR MENSAJE PARA CERRAR EL BACHE ANTERIOR (UPDATE)
    msgUpdate = {
        topic: "UPDATE baches SET fecha_fin = ? WHERE fecha_fin IS NULL",
        // Parámetro: [fecha_fin]
        params: [sqlDate],
        payload: currentDensity // Puedes mantener la densidad en el payload si la necesitas para algo más
    };

    // 2. CREAR MENSAJE PARA ABRIR EL NUEVO BACHE (INSERT)
    msgInsert = {
        // La consulta de INSERT
        topic: "INSERT INTO baches (fecha_inicio, densidad_prom, producto_id) VALUES (?, ?, ?)",
        // Parámetros: [fecha_inicio, densidad_prom, producto_id]
        params: [sqlDate, currentDensity, producto],
        payload: currentDensity
    };

    node.warn(`¡Cambio de Producto! Cerrando bache anterior y abriendo nuevo de ${inLineProduct}.`);
}

// Devuelve un array de mensajes: [Salida 1, Salida 2]
// Salida 1: Cierre (Update)
// Salida 2: Apertura (Insert)
return [msgUpdate, msgInsert, msgPause];

// Suponiendo que msg.payload es el array de alarmas original
