    } else if (item.Alerta === "LOW" || item.Alerta === "LL") {
        bgColor = "#2196f3";  // azul
        icon = "🔻";
    } else if (item.Alerta === "OK" || item.Alerta === "NORMAL") {
        bgColor = "#4caf50";  // verde
        icon = "✔️";
    }

    return {
        DATE: item.DATE,
        TAG: item.TAG,
        Valor: item.Valor,
        Descripcion: item.Descripcion,
        Alerta: item.Alerta,
        Unidad: item.Unidad,
        bgColor: bgColor,
        textColor: textColor,
        icon: icon
    };
});

return msg;

