// Cálculo del peso molecular
function calcularPesoMolecular(cromatografia) {
    const pesosMoleculares = {
        C1: 16.043, C2: 30.070, C3: 44.097,
        iC4: 58.123, nC4: 58.123,
        iC5: 72.150, nC5: 72.150,
        C6: 86.177, C7: 100.204, C8: 114.231, C9: 128.258,
        H2O: 18.015, CO2: 44.010, N2: 28.013, H2S: 34.082
    };
    return Object.keys(cromatografia).reduce((sum, componente) =>
        sum + cromatografia[componente] * pesosMoleculares[componente], 0);
}

const MW = calcularPesoMolecular(cromatografia);

// Cálculo del factor de compresibilidad (Z)
// Nota: Este es un cálculo simplificado. Para mayor precisión, se recomienda
// usar métodos más avanzados como la ecuación de estado AGA8 o GERG-2008
function calcularFactorCompresibilidad(P, T, MW) {
    const Pc = 667 + 15 * MW - 0.05 * Math.pow(MW, 2); // Presión crítica estimada
    const Tc = 343 + 7 * MW - 0.01 * Math.pow(MW, 2); // Temperatura crítica estimada
    const Tr = (T + 460) / Tc; // Temperatura reducida
    const Pr = P / Pc; // Presión reducida
    return 1 - (0.06 + 0.01 * Pr) / Tr;
}

// Implementación simplificada del método AGA8-DC92
function calcularFactorCompresibilidadAGA8(P, T, composicion) {
    // Constantes para los componentes (orden: C1, C2, C3, iC4, nC4, iC5, nC5, N2, CO2)
    const Tc = [190.56, 305.32, 369.83, 407.8, 425.12, 460.4, 469.7, 126.2, 304.12]; // K
    const Pc = [45.99, 48.72, 42.48, 36.4, 37.96, 33.8, 33.7, 33.98, 73.74]; // bar
    const omega = [0.0115, 0.0995, 0.1523, 0.1852, 0.2010, 0.2275, 0.2510, 0.0377, 0.2239];

    // Convertir temperatura a Kelvin y presión a bar
    const Tk = (T + 459.67) * 5/9;
    const Pbar = P * 0.0689476;

    // Calcular parámetros de mezcla
    let Tcm = 0, Pcm = 0, omega_m = 0;
    const componentes = ['C1', 'C2', 'C3', 'iC4', 'nC4', 'iC5', 'nC5', 'N2', 'CO2'];
    componentes.forEach((comp, i) => {
        const xi = composicion[comp];
        Tcm += xi * Tc[i];
        Pcm += xi * Pc[i];
        omega_m += xi * omega[i];
    });

    // Calcular factor acéntrico de mezcla
    const omega_m_adj = 0.3796 + 1.5226 * omega_m - 0.2967 * Math.pow(omega_m, 2);

    // Calcular Z usando la ecuación de estado de Peng-Robinson
    const R = 8.3145; // Constante de gas universal en J/(mol·K)
    const a = 0.45724 * Math.pow(R * Tcm, 2) / Pcm * Math.pow(1 + (0.37464 + 1.54226 * omega_m_adj - 0.26992 * Math.pow(omega_m_adj, 2)) * (1 - Math.sqrt(Tk / Tcm)), 2);
    const b = 0.0778 * R * Tcm / Pcm;

    const A = a * Pbar / Math.pow(R * Tk, 2);
    const B = b * Pbar / (R * Tk);

    const coef = [1, -(1-B), A-3*Math.pow(B,2)-2*B, -(A*B-Math.pow(B,2)-Math.pow(B,3))];

    // Resolver la ecuación cúbica para Z
    const roots = solveCubic(coef);
    const Z = Math.max(...roots); // Tomar la raíz más grande

    return Z;
}

// Función auxiliar para resolver ecuaciones cúbicas
function solveCubic(coef) {
    const [a, b, c, d] = coef;
    const p = (3*a*c - Math.pow(b,2)) / (3*Math.pow(a,2));
    const q = (2*Math.pow(b,3) - 9*a*b*c + 27*Math.pow(a,2)*d) / (27*Math.pow(a,3));
    const D = Math.pow(q/2,2) + Math.pow(p/3,3);

    if (D > 0) {
        const u = Math.cbrt(-q/2 + Math.sqrt(D));
        const v = Math.cbrt(-q/2 - Math.sqrt(D));
        return [u + v - b/(3*a)];
    } else if (D === 0) {
        const u = Math.cbrt(-q/2);
        return [2*u - b/(3*a), -u - b/(3*a)];
    } else {
        const phi = Math.acos(-q / (2*Math.sqrt(Math.pow(-p/3,3))));
        const r = 2 * Math.sqrt(-p/3);
        return [
            r * Math.cos(phi/3) - b/(3*a),
            r * Math.cos((phi + 2*Math.PI)/3) - b/(3*a),
            r * Math.cos((phi + 4*Math.PI)/3) - b/(3*a)
        ];
    }
}

