// Función actualizada para calcular Cd usando el número de Reynolds
function calcularCd(beta, D, P, dP, Re) {
    // Esta es una versión simplificada. La ecuación completa es más compleja.
    const L1 = 0.0254 / D; // Asumiendo una toma de presión en la esquina
    const L2 = 0.0254 / D;
    const A = Math.pow(19000 * beta / Re, 0.8);

    return 0.5961 + 0.0261 * Math.pow(beta, 2) - 0.216 * Math.pow(beta, 8) +
           0.000521 * Math.pow(1e6 * beta / Re, 0.7) +
           (0.0188 + 0.0063 * A) * Math.pow(beta, 3.5) * Math.pow(1e6 / Re, 0.3) +
           (0.043 + 0.080 * Math.exp(-10 * L1) - 0.123 * Math.exp(-7 * L1)) * 
           (1 - 0.11 * A) * Math.pow(beta, 4) / (1 - Math.pow(beta, 4)) -
           0.031 * (L2 - 0.8 * Math.pow(L2, 1.1)) * Math.pow(beta, 1.3);
}


// Función para calcular el número de Reynolds
function Reynolds(D, P, T, MW, dP, Z) {
    const mu = 1.8e-5; // Viscosidad dinámica estimada en Pa·s
    const rho = P * MW / (Z * 10.73 * (T + 460)); // Densidad del gas en lb/ft³
    const velocidad = 0.0119 * Math.sqrt(dP * P / (MW * (T + 460))); // Velocidad en ft/s
    return 7000 * rho * velocidad * D / mu; // Reynolds (adimensional)
}



