    llenado_id = global.get("ID_LLENADO2");
}

// Debug para ver qué valores tienes
node.warn("sel_cisterna: " + sel_cisterna);
node.warn("llenado_id: " + llenado_id);

// Validar que sea un número mayor a 0
if (llenado_id && llenado_id > 0) {
    msg.topic = `SELECT * FROM llenado_promedios WHERE llenado_id = ${llenado_id}`;
    msg.payload = llenado_id;
    return msg;
}

// Si no hay ID válido, no continuar el flujo
node.warn("llenado_id no válido: " + llenado_id);

let data=msg.payload;

let sel_cisterna=global.get("SEL_CISTERNA");
let sel_segment=sel_cisterna==="CISTERNA1" ? "FILL_SEGMENT1":"FILL_SEGMENT2";

global.set(sel_segment,data);


let noPlaca=global.get("NoPLACA");
if(noPlaca==null)
{
    node.warn("Seleccione una CISTERNA");
}

msg.params=[noPlaca]
return msg;

/*
CREATE TABLE "llenados" (
	"id"	INTEGER,
	"cisterna_id"	INTEGER NOT NULL,
	"fecha_inicio"	DATETIME NOT NULL,
	"fecha_fin"	DATETIME,
	"producto_id"	INTEGER NOT NULL,
	"volumen_objetivo"	REAL,
	"volumen_actual"	REAL DEFAULT 0,
	"estado"	TEXT NOT NULL DEFAULT 'EN_PROCESO',
	"RVP"	REAL NOT NULL DEFAULT 180,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("cisterna_id") REFERENCES "cisternas"("id"),
	FOREIGN KEY("producto_id") REFERENCES "productos"("id")
)
*/

let date_string = new Date().toLocaleString('en-US', { hour12: false }).replaceAll('/', '-');
date_string = date_string.replace(',', ' ');

let sel_cisterna = global.get("SEL_CISTERNA");
var datos={};
let id_cisterna = msg.payload[0].id;
let id_product = datos.producto == "PROPANO" ? 1 : 2;
let status_cisterna=0;

if(sel_cisterna=== "CISTERNA1")
{
	datos= global.get("FILL_SEGMENT1");
	global.set("ID_PRODUCTO1", id_product);
	global.set("ID_CISTERNA1", id_cisterna);
	status_cisterna=global.get("STATUS_CISTERNA1");

}
else
{
	datos = global.get("FILL_SEGMENT2");
	global.set("ID_PRODUCTO2", id_product);
	global.set("ID_CISTERNA2", id_cisterna);
	status_cisterna==global.get("STATUS_CISTERNA2");

}



if (msg.topic === "OK" && (status_cisterna === 0 || status_cisterna === 4)) {
	msg.payload = "UpdateData";
	let promedios = {

		llenado_id: 0,
		flujo_promedio: 0.0,
		densidad_promedio: 0.0,
		presion_promedio: 0.0,
		temperatura_promedio: 0.0,
		volumen_total: 0

	};
	global.set("PROMEDIOS", promedios);
	// Mapeamos los valores a los parámetros del query
	msg.params = [id_cisterna, date_string, id_product, datos.Vol_full, 0, datos.rvp];
	if (sel_cisterna === "CISTERNA1") 
	{
		global.set("STATUS_CISTERNA1", 1);
		global.set("CISTERNA2_VISIBLE",1);
	}
	else {
		global.set("STATUS_CISTERNA2", 1);
		global.set("CISTERNA1_VISIBLE",1);
	}


}
else {
	msg.payload = null;
}
return msg;

if(global.get("SEL_CISTERNA")=== "CISTERNA1")
{
    global.set("ID_LLENADO1",msg.payload[0].id_llenado);

}
else
{
    global.set("ID_LLENADO2",msg.payload[0].id_llenado);
}


msg.payload=msg.payload[0].id_llenado;
return msg;

// Ejemplo de cómo manejar las acciones
const data = msg.payload;
const action = msg.topic;
const sel_cisterna=global.get("SEL_CISTERNA");

switch(action) {
    case "CISTERNA_SELECCIONADA":
        global.set("NoPLACA",data.placa);
        let dtCisterna=global.get(sel_cisterna);
        dtCisterna.numero_sisterna=data.placa;
        dtCisterna.empresa_cliente=data.cliente;
        dtCisterna.galones_objetivo=data.capacidad;
        global.set(sel_cisterna,dtCisterna);
        global.set("NoPLACA",data.placa);
        msg.payload=null;
        break;
    case "INSERT":
        msg.topic = `INSERT INTO cisternas (placa, cliente, capacidad, activa) VALUES ('${data.placa}', '${data.cliente}', ${data.capacidad}, ${data.activa})`;
        break;
    case "UPDATE":
        msg.topic = `UPDATE cisternas SET placa='${data.placa}', cliente='${data.cliente}', capacidad=${data.capacidad}, activa=${data.activa} WHERE id=${data.id}`;
        break;
    case "DELETE":
        msg.topic = `DELETE FROM cisternas WHERE id=${data.id}`;
        break;
    default:
        msg.payload=null;    
}

return msg;

node.warn("SEL_CISTERNA: " + global.get("SEL_CISTERNA"));
node.warn("ID_LLENADO1: " + global.get("ID_LLENADO1"));
node.warn("ID_LLENADO2: " + global.get("ID_LLENADO2"));

return msg;
